// Package model is PatchTriage's normalized data model.
//
// Every scanner output (Trivy, Grype, OSV, ...) is mapped into RawFinding.
// Dedup merges RawFindings into Finding (one per CVE x package x asset).
// Enrichment attaches authoritative signals (EPSS / KEV / NVD and vendor
// advisories); these values are always fetched deterministically, never
// generated by an LLM. JSON field names match the Python implementation so
// reports and the GUI API stay interchangeable.
package model

import (
	"encoding/json"
	"fmt"
	"reflect"
	"regexp"
	"strconv"
	"strings"
	"time"
)

var ecosystemAliases = map[string]string{
	"apk": "alpine", "cargo": "crates.io", "composer": "packagist",
	"cratesio": "crates.io", "deb": "debian", "gem": "rubygems", "go": "golang",
	// Java coordinates arrive under several scanner spellings; they all
	// identify the same Maven groupId:artifactId.
	"gradle": "maven", "jar": "maven", "java": "maven", "javaarchive": "maven",
	"pom": "maven", "node": "npm", "nodejs": "npm", "pip": "pypi",
	"python": "pypi", "unknown": "",
}

var ecosystemSeparators = regexp.MustCompile(`[\s_.-]+`)

// NormalizeEcosystem gives one spelling per ecosystem without collapsing
// distinct distributions: PyPI/python/pip -> pypi, go -> golang.
func NormalizeEcosystem(value string) string {
	normalized := ecosystemSeparators.ReplaceAllString(strings.ToLower(strings.TrimSpace(value)), "")
	if alias, ok := ecosystemAliases[normalized]; ok {
		return alias
	}
	return normalized
}

// unquote percent-decodes like Python's urllib.parse.unquote: invalid
// escapes are kept literally instead of failing.
func unquote(s string) string {
	if !strings.Contains(s, "%") {
		return s
	}
	var b strings.Builder
	for i := 0; i < len(s); i++ {
		if s[i] == '%' && i+2 < len(s) {
			if v, err := strconv.ParseUint(s[i+1:i+3], 16, 8); err == nil {
				b.WriteByte(byte(v))
				i += 2
				continue
			}
		}
		b.WriteByte(s[i])
	}
	return b.String()
}

// ParsePurl splits a package URL into (type, namespace, name, version).
// Qualifiers and subpaths are dropped; components are percent-decoded.
// Every value is empty when purl is not a package URL.
func ParsePurl(purl string) (typ, namespace, name, version string) {
	value := strings.TrimSpace(purl)
	if !strings.HasPrefix(strings.ToLower(value), "pkg:") {
		return
	}
	body := strings.SplitN(strings.SplitN(value[4:], "#", 2)[0], "?", 2)[0]
	purlType, path, ok := strings.Cut(body, "/")
	if !ok {
		return
	}
	if at := strings.LastIndex(path, "@"); at > 0 { // a leading "@" is an npm scope
		version = unquote(path[at+1:])
		path = path[:at]
	}
	var parts []string
	for _, part := range strings.Split(path, "/") {
		if part != "" {
			parts = append(parts, unquote(part))
		}
	}
	if len(parts) == 0 {
		return "", "", "", ""
	}
	return strings.ToLower(purlType), strings.Join(parts[:len(parts)-1], "/"), parts[len(parts)-1], version
}

// Severity is the scanner-reported severity label.
type Severity string

const (
	SeverityCritical   Severity = "critical"
	SeverityHigh       Severity = "high"
	SeverityMedium     Severity = "medium"
	SeverityLow        Severity = "low"
	SeverityNegligible Severity = "negligible"
	SeverityUnknown    Severity = "unknown"
)

var severityRank = map[Severity]int{
	SeverityUnknown: 0, SeverityNegligible: 0, SeverityLow: 1,
	SeverityMedium: 2, SeverityHigh: 3, SeverityCritical: 4,
}

// ParseSeverity maps scanner spellings onto Severity; anything else is unknown.
func ParseSeverity(value string) Severity {
	v := strings.ToLower(strings.TrimSpace(value))
	switch v {
	case "moderate":
		v = "medium"
	case "important":
		v = "high"
	}
	if _, ok := severityRank[Severity(v)]; ok {
		return Severity(v)
	}
	return SeverityUnknown
}

// SeverityRank orders severities for conservative merging (critical = 4).
func SeverityRank(s Severity) int { return severityRank[s] }

// Package is the vulnerable component.
type Package struct {
	Name      string `json:"name"`
	Version   string `json:"version"`
	Ecosystem string `json:"ecosystem"`
	Purl      string `json:"purl"`
	// "" = the version came from the evidence itself; otherwise how it was chosen.
	VersionSource string `json:"version_source"`
	FixedVersion  string `json:"fixed_version"`
	// Conflicting scanner/vendor fix values are retained for auditable selection.
	FixedVersionCandidates []string `json:"fixed_version_candidates"`
}

func (p Package) MarshalJSON() ([]byte, error) {
	type alias Package
	return marshalFilled(alias(p))
}

var assetChoices = map[string][]string{
	"system_exposure":       {"controlled", "open", "small", "unknown"},
	"automatable":           {"no", "unknown", "yes"},
	"mission_impact":        {"degraded", "mef_failure", "mef_support_crippled", "mission_failure", "unknown"},
	"safety_impact":         {"catastrophic", "critical", "marginal", "negligible", "unknown"},
	"publicly_exposed":      {"no", "unknown", "yes"},
	"bod2604_applicability": {"not_applicable", "required", "unknown", "voluntary"},
}

// NormalizeChoice applies the Python validator rules for one SSVC or policy
// context field: lower-case, "-" -> "_", empty -> "unknown", then validate.
func NormalizeChoice(field, value string) (string, error) {
	normalized := strings.ReplaceAll(strings.ToLower(strings.TrimSpace(value)), "-", "_")
	if normalized == "" {
		normalized = "unknown"
	}
	allowed, ok := assetChoices[field]
	if !ok {
		return "", fmt.Errorf("unknown context field %q", field)
	}
	for _, choice := range allowed {
		if normalized == choice {
			return normalized, nil
		}
	}
	return "", fmt.Errorf("%s must be one of: %s", field, strings.Join(allowed, ", "))
}

// Asset is where the vulnerable component lives.
type Asset struct {
	Identifier      string `json:"identifier"`
	Kind            string `json:"kind"`
	Criticality     string `json:"criticality"`
	InternetExposed *bool  `json:"internet_exposed"`
	Reachable       *bool  `json:"reachable"`
	RuntimeObserved *bool  `json:"runtime_observed"`
	// SSVC Deployer context. "unknown" invokes the documented conservative
	// default and is surfaced for confirmation rather than hidden.
	SystemExposure string `json:"system_exposure"`
	Automatable    string `json:"automatable"`
	MissionImpact  string `json:"mission_impact"`
	SafetyImpact   string `json:"safety_impact"`
	// CISA BOD 26-04 inputs: Publicly Exposed is not SSVC System Exposure.
	PubliclyExposed      string   `json:"publicly_exposed"`
	BOD2604Applicability string   `json:"bod2604_applicability"`
	ContextSources       []string `json:"context_sources"`
	Owner                string   `json:"owner"`
	ContextNotes         string   `json:"context_notes"`
}

// NewAsset returns an asset with every context value "unknown".
func NewAsset(identifier string) Asset {
	return Asset{
		Identifier: identifier, Kind: "unknown", Criticality: "unknown",
		SystemExposure: "unknown", Automatable: "unknown", MissionImpact: "unknown",
		SafetyImpact: "unknown", PubliclyExposed: "unknown", BOD2604Applicability: "unknown",
		ContextSources: []string{},
	}
}

// Normalize validates and normalizes the SSVC and policy context fields.
func (a *Asset) Normalize() error {
	for field, target := range map[string]*string{
		"system_exposure": &a.SystemExposure, "automatable": &a.Automatable,
		"mission_impact": &a.MissionImpact, "safety_impact": &a.SafetyImpact,
		"publicly_exposed": &a.PubliclyExposed, "bod2604_applicability": &a.BOD2604Applicability,
	} {
		value, err := NormalizeChoice(field, *target)
		if err != nil {
			return err
		}
		*target = value
	}
	return nil
}

func (a Asset) MarshalJSON() ([]byte, error) {
	type alias Asset
	return marshalFilled(alias(a))
}

