// marshalFilled marshals v (a struct value) with nil slices emitted as []
// and nil maps as {}, matching pydantic's default_factory output. Fields
// tagged `nullable:"true"` keep null.
func marshalFilled(v any) ([]byte, error) {
	rv := reflect.ValueOf(v)
	copyValue := reflect.New(rv.Type()).Elem()
	copyValue.Set(rv)
	for i := 0; i < copyValue.NumField(); i++ {
		field := copyValue.Field(i)
		if copyValue.Type().Field(i).Tag.Get("nullable") == "true" || !field.CanSet() {
			continue
		}
		switch field.Kind() {
		case reflect.Slice:
			if field.IsNil() {
				field.Set(reflect.MakeSlice(field.Type(), 0, 0))
			}
		case reflect.Map:
			if field.IsNil() {
				field.Set(reflect.MakeMap(field.Type()))
			}
		case reflect.String:
			if field.Type() == reflect.TypeOf(Severity("")) && field.String() == "" {
				field.SetString(string(SeverityUnknown))
			}
		}
	}
	return json.Marshal(copyValue.Interface())
}
